/* Base Styles */
:root {
  --brand-primary: oklch(55% 0.22 260); /* vibrant, modern blue */
  --brand-primary-dark: oklch(45% 0.22 260);
  --brand-primary-light: oklch(95% 0.05 260);
  --brand-accent: oklch(65% 0.15 160); /* warm teal */
  --brand-accent-hover: oklch(55% 0.15 160);
  --bg-surface: oklch(100% 0 0); /* white */
  --bg-subtle: oklch(97% 0.01 260); /* light gray/blue */
  --bg-subtle-hover: oklch(94% 0.01 260);
  --text-primary: oklch(25% 0.02 260); /* near black */
  --text-secondary: oklch(45% 0.02 260); /* muted text */
  --text-inverse: oklch(100% 0 0);
  --border-light: oklch(90% 0.01 260);

  --shadow-sm: 0 4px 6px -1px oklch(0% 0 0 / 0.05), 0 2px 4px -1px oklch(0% 0 0 / 0.03);
  --shadow-md: 0 10px 25px -5px oklch(0% 0 0 / 0.05), 0 4px 10px -2px oklch(0% 0 0 / 0.025);
  --shadow-lg: 0 20px 40px -5px oklch(0% 0 0 / 0.08), 0 10px 15px -5px oklch(0% 0 0 / 0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --transition: 0.2s ease-in-out;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text-primary);
  background-color: var(--bg-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

button, input, select {
  font-family: inherit;
  font-size: inherit;
  border: none;
  background: none;
  outline: none;
}

button {
  cursor: pointer;
}

/* Typography */
h1, h2, h3, h4 {
  color: var(--text-primary);
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: -0.02em;
}

h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 1.5rem;
}

h2 {
  font-size: clamp(2rem, 4vw, 2.5rem);
  margin-bottom: 1rem;
}

h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

p {
  color: var(--text-secondary);
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
}

/* Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 6rem 0;
}

.section-light {
  background-color: var(--bg-surface);
}

.section-subtle {
  background-color: var(--bg-subtle);
}

.section-primary {
  background-color: var(--brand-primary);
  color: var(--text-inverse);
}

.section-primary h2, 
.section-primary p {
  color: var(--text-inverse);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  transition: all var(--transition);
  text-align: center;
}

.btn-primary {
  background-color: var(--brand-primary);
  color: var(--text-inverse);
}

.btn-primary:hover {
  background-color: var(--brand-primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background-color: var(--brand-accent);
  color: var(--text-inverse);
}

.btn-accent:hover {
  background-color: var(--brand-accent-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background-color: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-light);
}

.btn-outline:hover {
  background-color: var(--bg-subtle);
  border-color: var(--text-secondary);
}

.btn-white {
  background-color: var(--bg-surface);
  color: var(--brand-primary);
}

.btn-white:hover {
  background-color: var(--bg-subtle);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border-light);
  padding: 1rem 0;
}

.header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--brand-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-desktop a {
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition);
}

.nav-desktop a:hover {
  color: var(--brand-primary);
}

.nav-desktop .btn {
  color: var(--text-inverse);
}

.nav-desktop .btn:hover {
  color: var(--text-inverse);
}

.menu-toggle {
  display: none;
  font-size: 1.5rem;
  color: var(--text-primary);
}

/* Mobile Nav Drawer */
.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 100%;
  height: 100vh;
  background-color: var(--bg-surface);
  z-index: 200;
  padding: 2rem;
  transition: right 0.3s ease-in-out;
  display: flex;
  flex-direction: column;
}

.mobile-nav.active {
  right: 0;
}

.mobile-nav-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3rem;
}

.mobile-nav-close {
  font-size: 1.5rem;
  color: var(--text-primary);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  font-size: 1.25rem;
  font-weight: 600;
}

.mobile-nav-links a {
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--border-light);
}

.mobile-nav-actions {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Hero Section */
.hero {
  text-align: center;
  padding: 6rem 0 4rem;
  background: linear-gradient(180deg, var(--brand-primary-light) 0%, var(--bg-surface) 100%);
  position: relative;
  overflow: hidden;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  z-index: 10;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 3rem;
}

/* Search Bar Component */
.search-container {
  background-color: var(--bg-surface);
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-lg);
  padding: 0.5rem;
  display: flex;
  align-items: center;
  border: 1px solid var(--border-light);
  max-width: 900px;
  margin: 0 auto;
  position: relative;
  text-align: left;
}

.search-field {
  flex: 1;
  padding: 1rem 1.5rem;
  border-right: 1px solid var(--border-light);
  position: relative;
}

.search-field:last-of-type {
  border-right: none;
}

.search-label {
  display: block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
}

.search-input {
  width: 100%;
  font-size: 1rem;
  color: var(--text-primary);
}

.search-input::placeholder {
  color: var(--text-secondary);
  opacity: 0.7;
}

.search-btn {
  padding: 1rem 2rem;
  height: 100%;
  border-radius: var(--radius-full);
  font-size: 1rem;
}

/* Search Autocomplete Dropdown */
.search-dropdown {
  position: absolute;
  top: calc(100% + 1rem);
  left: 0;
  width: 100%;
  background-color: var(--bg-surface);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border-light);
  z-index: 50;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px);
  transition: all var(--transition);
}

.search-dropdown.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-list {
  padding: 0.5rem 0;
}

.dropdown-item {
  padding: 0.75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  cursor: pointer;
  transition: background-color var(--transition);
}

.dropdown-item:hover {
  background-color: var(--bg-subtle);
}

.dropdown-item svg {
  color: var(--brand-primary);
  width: 1.25rem;
  height: 1.25rem;
}

/* Stats Section */
.stats {
  padding: 3rem 0;
  border-bottom: 1px solid var(--border-light);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-value {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--brand-primary);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 1rem;
  color: var(--text-secondary);
  font-weight: 500;
}

/* Specialties Section */
.specialties-header {
  text-align: center;
  margin-bottom: 3rem;
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.specialty-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  transition: all var(--transition);
  cursor: pointer;
}

.specialty-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--brand-primary);
}

.specialty-icon {
  width: 3.5rem;
  height: 3.5rem;
  background-color: var(--brand-primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-primary);
}

.specialty-icon svg {
  width: 1.75rem;
  height: 1.75rem;
}

.specialty-info h3 {
  margin-bottom: 0;
  font-size: 1.125rem;
}

.specialty-info p {
  margin-bottom: 0;
  font-size: 0.875rem;
}

/* How It Works */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  margin-top: 4rem;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 4rem;
  height: 4rem;
  background-color: var(--brand-primary);
  color: var(--text-inverse);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  margin: 0 auto 1.5rem;
  box-shadow: var(--shadow-md);
}

.step-card h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.step-card p {
  font-size: 1rem;
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.testimonial-card {
  background-color: var(--bg-surface);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  display: flex;
  flex-direction: column;
}

.stars {
  color: var(--brand-accent);
  display: flex;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

.stars svg {
  width: 1.25rem;
  height: 1.25rem;
  fill: currentColor;
}

.testimonial-quote {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  flex-grow: 1;
}

.testimonial-author {
  font-weight: 700;
  color: var(--text-primary);
}

.testimonial-location {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Mobile App Promo */
.app-promo-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.app-store-buttons {
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
}

.app-btn {
  background-color: var(--text-primary);
  color: var(--text-inverse);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  transition: all var(--transition);
}

.app-btn:hover {
  background-color: black;
  transform: translateY(-2px);
}

.app-btn-icon {
  width: 1.5rem;
  height: 1.5rem;
}

.app-btn-text span {
  display: block;
  font-size: 0.7rem;
  text-transform: uppercase;
}

.app-btn-text strong {
  font-size: 1.1rem;
  font-weight: 600;
}

.app-mockup {
  position: relative;
  width: 100%;
  max-width: 320px;
  margin: 0 auto;
}

.phone-frame {
  background-color: var(--bg-surface);
  border-radius: 40px;
  padding: 0.75rem;
  box-shadow: var(--shadow-lg);
  position: relative;
}

.phone-screen {
  background-color: var(--bg-subtle);
  border-radius: 32px;
  overflow: hidden;
  position: relative;
  aspect-ratio: 9/19;
  display: flex;
  flex-direction: column;
}

.phone-header {
  padding: 1rem;
  background-color: var(--brand-primary);
  color: white;
  text-align: center;
  font-weight: 600;
}

.phone-body {
  padding: 1rem;
  flex: 1;
}

.mockup-card {
  background-color: white;
  border-radius: var(--radius-md);
  padding: 1rem;
  margin-bottom: 1rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  gap: 1rem;
}

.mockup-avatar {
  width: 3rem;
  height: 3rem;
  border-radius: var(--radius-full);
  background-color: var(--brand-primary-light);
}

.mockup-lines {
  flex: 1;
}

.mockup-line {
  height: 0.5rem;
  background-color: var(--bg-subtle);
  border-radius: 4px;
  margin-bottom: 0.5rem;
}

.mockup-line.short {
  width: 60%;
}

/* Footer */
.footer {
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-light);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  margin-bottom: 1rem;
}

.footer-col h4 {
  font-size: 1rem;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--brand-primary);
}

.footer-bottom {
  border-top: 1px solid var(--border-light);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-secondary);
  font-size: 0.875rem;
}

/* Responsive Design */
@media (max-width: 1024px) {
  .search-container {
    flex-direction: column;
    border-radius: var(--radius-xl);
    padding: 1rem;
    gap: 1rem;
  }

  .search-field {
    border-right: none;
    border-bottom: 1px solid var(--border-light);
    width: 100%;
  }

  .search-field:last-of-type {
    border-bottom: none;
  }

  .search-btn {
    width: 100%;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  h1 {
    font-size: 2.25rem;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .app-promo-content {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .app-store-buttons {
    justify-content: center;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-brand {
    grid-column: span 2;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .specialties-grid {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: span 1;
  }

  .app-store-buttons {
    flex-direction: column;
  }
}

